<?php
function sc_audit($event,$id=null){if(empty($_SESSION[USER_AUTH]))return;$event=preg_replace('/[^a-zA-Z0-9_. -]/','',(string)$event);$message='[admin] '.$event.($id!==null?' | record '.(int)$id:'');sc_query('INSERT INTO admin_updates (updated_by,update_text) VALUES (?,?)','ss',[(string)$_SESSION[USER_AUTH],$message]);$GLOBALS['sc_audit_written']=true;}
function sc_public_setting($key,$default=''){ $value=systemVariable($key);return $value===null?$default:$value; }
function sc_site_fields(){return ['website_phone'=>['Phone number','+91 98615 72334',60],'website_email'=>['Email','say_hi@stepcure.co',150],'website_address'=>['Address','Bhubaneswar, Odisha',500],'website_hours'=>['Opening hours','Mon to Sat, 9am to 6pm',200],'website_whatsapp'=>['WhatsApp number','',30],'website_facebook'=>['Facebook URL','',250],'website_instagram'=>['Instagram URL','',250],'footer_kicker'=>['Footer eyebrow','CLINICAL CARE. EVERYDAY COMFORT.',150],'footer_heading'=>['Footer call to action','Take your next step',150],'footer_description'=>['Footer description','Personalized footcare, custom orthotics and footwear for the way you move.',600],'footer_copyright'=>['Copyright name','StepCure',100],'footer_cta_label'=>['Button label','Book a consultation',100]];}
function sc_save_public_settings($input,$keys){$values=[];foreach($keys as $key){$meta=sc_site_fields()[$key]??null;if(!$meta)continue;$value=trim($input[$key]??'');if(mb_strlen($value)>$meta[2])throw new RuntimeException($meta[0].' is too long.');if($key==='website_email'&&$value!==''&&!filter_var($value,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');if(in_array($key,['website_instagram','website_facebook'],true)&&$value!==''&&(!filter_var($value,FILTER_VALIDATE_URL)||!in_array(parse_url($value,PHP_URL_SCHEME),['https','http'],true)))throw new RuntimeException('Social links must be full http(s) URLs.');if(in_array($key,['website_phone','website_whatsapp'],true)&&$value!==''&&!preg_match('/^[0-9+() .-]{5,60}$/',$value))throw new RuntimeException('Enter a valid phone number.');$values[$key]=$value;}$db=sc_db();$db->begin_transaction();try{foreach($values as $key=>$value){$exists=sc_query('SELECT id FROM systemv WHERE variable=? LIMIT 1','s',[$key])->get_result()->fetch_assoc();if($exists)sc_query('UPDATE systemv SET value=? WHERE variable=?','ss',[$value,$key]);else sc_query('INSERT INTO systemv (variable,value) VALUES (?,?)','ss',[$key,$value]);}sc_audit('website_settings.saved');$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}}
function sc_task_action($request){if(!hash_equals(sc_csrf(),(string)($request['csrf']??'')))throw new RuntimeException('Your session expired. Reload the dashboard.');$user=(int)userVariable('id');if(!$user)throw new RuntimeException('Please sign in.');$db=sc_db();$db->begin_transaction();try{$action=$request['task_action']??'';if($action==='add'){$title=trim($request['title']??'');$due=trim($request['due_date']??'');if(!$title||mb_strlen($title)>150)throw new RuntimeException('Enter a follow-up of up to 150 characters.');if($due!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)||date('Y-m-d',strtotime($due))!==$due))throw new RuntimeException('Enter a valid due date.');sc_query('INSERT INTO admin_tasks (user_id,title,due_date) VALUES (?,?,?)','iss',[$user,$title,$due?:null]);$id=sc_db()->insert_id;sc_audit('followup.created',$id);}elseif($action==='complete'){$id=filter_var($request['task_id']??0,FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid follow-up.');$s=sc_query('UPDATE admin_tasks SET is_done=1 WHERE id=? AND user_id=? AND is_done=0','ii',[$id,$user]);if($s->affected_rows)sc_audit('followup.completed',$id);}else throw new RuntimeException('Invalid follow-up action.');$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}return sc_query('SELECT id,title,due_date FROM admin_tasks WHERE user_id=? AND is_done=0 ORDER BY due_date IS NULL,due_date,id DESC LIMIT 10','i',[$user])->get_result()->fetch_all(MYSQLI_ASSOC);}
